INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 17, 'theory', 'Квиз: CSS — каскад, наследование, единицы и переменные');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 0, 'Абзац имеет класс lead и идентификатор intro. Какой цвет текста он получит при правилах p { color: red; }, #intro { color: green; } и .lead { color: blue; }?', '["красный: правило для p записано первым","зелёный: селектор по идентификатору самый специфичный","синий: класс записан в разметке последним","цвет выберется случайно"]', 1, 'Побеждает объявление с большей специфичностью: идентификатор весит больше класса, а класс больше названия элемента. Порядок записи учитывается только при равной специфичности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 1, 'Почему злоупотреблять пометкой !important вредно?', '["Перебить её можно только такой же пометкой и более специфичным селектором, и стили превращаются в гонку вооружений","Она отключает наследование у всех потомков","Браузер игнорирует её во внешних файлах стилей","Она замедляет разбор страницы в несколько раз"]', 0, 'Пометка важности поднимает объявление над обычными, поэтому единственный способ его переопределить — ещё одна пометка. Оправданна она в служебных классах, а порядок лучше наводить слоями и низкой специфичностью.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 2, 'Какое свойство наследуется потомками по умолчанию?', '["margin","border","background","color"]', 3, 'Наследуются свойства текста: цвет, шрифт, высота строки, выравнивание. Отступы, рамки, фон и размеры не наследуются, иначе рамка рисовалась бы заново в каждой вложенной карточке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 3, 'У родителя размер шрифта 20px. Элемент внутри задаёт font-size: 1.5em, а его потомок снова font-size: 1.5em. Какой размер получит потомок?', '["30px","20px","45px","24px"]', 2, 'Эм считается от шрифта родителя, поэтому значения перемножаются: 20 × 1,5 = 30, затем 30 × 1,5 = 45. Рем таких сюрпризов не даёт: он всегда считается от шрифта корневого элемента.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 4, 'Переменную --accent объявили на :root, а внутри блока .card задали ей другое значение. Что произойдёт?', '["Значение изменится на всей странице","Новое значение увидят только .card и его потомки, остальные останутся с прежним","Браузер выдаст ошибку: переопределять переменные нельзя","Новое значение проигнорируется, потому что корень главнее"]', 1, 'Пользовательские свойства участвуют в каскаде и наследуются: значение, заданное в блоке, действует внутри него и в потомках. Именно на этом строятся темы оформления.');
